/// A non-2xx answer from the hub, or a body that is not the API's error shape.
final class ApiException implements Exception {
  const ApiException(this.status, this.code, this.message);

  final int status;
  final ErrorCode code;
  final String message;

  @override
  String toString() => '${code.wire}: $message';
}

ApiException _error(int status, String body) {
  try {
    final e = ErrorBody.fromJson(jsonDecode(body)).error;
    return ApiException(status, e.code, e.message);
  } on FormatException {
    final text = body.length > 200 ? '${body.substring(0, 200)}...' : body;
    return ApiException(status, ErrorCode.unknown, 'HTTP $status $text');
  }
}

/// The hub API: `POST /api/<Method>` per method and the `GET /api/events` WebSocket.
/// `baseUrl` is the hub's origin, such as `https://hub.example.lan`; `token` a
/// `pd1.` device token or another bearer credential.
final class HubApi {
  HubApi(this.baseUrl, {this.token});

  final Uri baseUrl;
  final String? token;

  Uri _url(String path, [Map<String, String>? query]) {
    final base = baseUrl.path.endsWith('/')
        ? baseUrl.path.substring(0, baseUrl.path.length - 1)
        : baseUrl.path;
    return baseUrl.replace(path: '$base$path', queryParameters: query);
  }

  Future<T> _call<T>(
    String method,
    Map<String, Object?> request,
    T Function(Object?) parse,
  ) async {
    final r = await postJson(_url('/api/$method'), jsonEncode(request), token);
    if (r.status < 200 || r.status > 299) throw _error(r.status, r.body);
    return parse(jsonDecode(r.body));
  }

  /// State changes, starting with a snapshot unless the hub still holds every message from
  /// `fromSeq`. The stream ends when the socket closes; reconnect with the last seq + 1.
  Stream<HubStreamMessage> events({int? fromSeq}) => openSocket(
    _url('/api/events', {if (fromSeq != null) 'from_seq': '$fromSeq'}),
    token,
  ).map((text) => HubStreamMessage.fromJson(jsonDecode(text)));

  /// The full snapshot.
  ///
  /// `POST /api/GetState`, scope `owner`.
  Future<HubState> getState([Empty request = const Empty()]) =>
      _call('GetState', request.toJson(), HubState.fromJson);

  /// `POST /api/ListSleeves`, scope `sleeve`.
  Future<SleeveList> listSleeves([Empty request = const Empty()]) =>
      _call('ListSleeves', request.toJson(), SleeveList.fromJson);

  /// `POST /api/GetTranscript`, scope `sleeve`.
  Future<Transcript> getTranscript(GetTranscriptRequest request) =>
      _call('GetTranscript', request.toJson(), Transcript.fromJson);

  /// `POST /api/SpawnSleeve`, scope `sleeve`.
  Future<Sleeve> spawnSleeve(SpawnSleeveRequest request) =>
      _call('SpawnSleeve', request.toJson(), Sleeve.fromJson);

  /// `POST /api/SendMessage`, scope `sleeve`.
  Future<Sent> sendMessage(SendMessageRequest request) =>
      _call('SendMessage', request.toJson(), Sent.fromJson);

  /// `POST /api/Interrupt`, scope `sleeve`.
  Future<Empty> interrupt(SleeveRef request) =>
      _call('Interrupt', request.toJson(), Empty.fromJson);

  /// Stops the sleeve and, for a root, every child in the same step.
  ///
  /// `POST /api/StopSleeve`, scope `sleeve`.
  Future<Accepted> stopSleeve(SleeveRef request) =>
      _call('StopSleeve', request.toJson(), Accepted.fromJson);

  /// Needs the owner's approval when Envoy asks during a turn an agent message started (D9).
  ///
  /// `POST /api/RemoveSleeve`, scope `sleeve`.
  Future<Accepted> removeSleeve(SleeveRef request) =>
      _call('RemoveSleeve', request.toJson(), Accepted.fromJson);

  /// `POST /api/StartSleeve`, scope `sleeve`.
  Future<Accepted> startSleeve(StartSleeveRequest request) =>
      _call('StartSleeve', request.toJson(), Accepted.fromJson);

  /// `POST /api/Resleeve`, scope `sleeve`.
  Future<Accepted> resleeve(ResleeveRequest request) =>
      _call('Resleeve', request.toJson(), Accepted.fromJson);

  /// Not built yet: answers `unavailable`.
  ///
  /// `POST /api/TakeoverTerminal`, scope `owner`.
  Future<Empty> takeoverTerminal(SleeveRef request) =>
      _call('TakeoverTerminal', request.toJson(), Empty.fromJson);

  /// `POST /api/ListApprovals`, scope `owner`.
  Future<ApprovalList> listApprovals(ListApprovalsRequest request) =>
      _call('ListApprovals', request.toJson(), ApprovalList.fromJson);

  /// `POST /api/Decide`, scope `owner`.
